const urls = $input.first().json.urls;
if (!Array.isArray(urls) || urls.length < 1 || urls.length > 10) {
  throw new Error('Enter an array of 1 to 10 authorized public HTTP(S) URLs in Select pages. No API requests were sent.');
}
if (urls.some(url => typeof url !== 'string' || !/^https?:\/\/[^\s]+$/i.test(url.trim()))) {
  throw new Error('Every entry must be an HTTP(S) URL without whitespace. No API requests were sent.');
}
const unique = [...new Set(urls.map(url => url.trim()))];
return unique.map(url => ({ json: { url } }));

const safeCell = value => {
  const text = value == null ? '' : String(value);
  // Keep spreadsheet software from interpreting source text as a formula.
  return /^[\s]*[=+@-]/.test(text) || /^[\t\r\n]/.test(text) ? "'" + text : text;
};
return $input.all().map((item, index) => {
  const response = item.json;
  const apiStatus = Number(response.statusCode);
  const requestedUrl = $('Prepare URLs').itemMatching(index).json.url;
  let body;
  try { body = typeof response.body === 'string' ? JSON.parse(response.body) : response.body; } catch {}
  const object = value => value && typeof value === 'object' && !Array.isArray(value);
  const valid = object(body) && body.ok === true && Number.isInteger(body.httpStatus)
    && typeof body.truncated === 'boolean' && typeof body.finalUrl === 'string'
    && object(body.openGraph) && object(body.twitter) && Array.isArray(body.jsonLd);
  let result = 'api_error';
  if (apiStatus >= 200 && apiStatus < 300) {
    result = !valid ? 'invalid_response'
      : body.httpStatus < 200 || body.httpStatus >= 300 ? 'source_http_error'
      : body.truncated ? 'partial_response' : 'observed';
  }
  // Never label metadata missing when retrieval failed or was truncated.
  const observed = result === 'observed';
  const fields = observed ? {
    title: body.title, description: body.description, canonical: body.canonical,
    og_title: body.openGraph.title, og_description: body.openGraph.description,
    og_image: body.openGraph.image, twitter_card: body.twitter.card,
  } : { title: '', description: '', canonical: '', og_title: '', og_description: '', og_image: '', twitter_card: '' };
  const absent = observed ? Object.entries(fields).filter(([, value]) => typeof value !== 'string' || !value.trim()).map(([name]) => name).join('; ') : '';
  const row = {
    requested_url: requestedUrl,
    final_url: valid ? body.finalUrl : '',
    result, api_status: Number.isFinite(apiStatus) ? apiStatus : '',
    source_status: valid ? body.httpStatus : '',
    truncated: valid ? body.truncated : '',
    ...fields,
    json_ld_blocks: observed ? body.jsonLd.length : '',
    absent_in_response: absent,
  };
  return { json: Object.fromEntries(Object.entries(row).map(([key, value]) => [key, typeof value === 'string' ? safeCell(value) : value])), pairedItem: { item: index } };
});
